Method.Source:
    protected LedgerJournalTrans initLedgerJournalTransFromPaymLine(
        LedgerJournalTrans          _ledgerJournalTrans,
        CustVendPaymProposalLine    _custVendPaymProposalLine)
    {
        str                         methodOfPaymeJL;
        boolean                     value;
        LedgerJournalName           lgName;


        LedgerJournalTrans LedgerJournalTransVar;
        LedgerJournalTransVar = next initLedgerJournalTransFromPaymLine(
            _ledgerJournalTrans,
           _custVendPaymProposalLine);

        methodOfPaymeJL = LedgerJournalName::find(ledgerJournalTable::find(_ledgerJournalTrans.JournalNum).JournalName).MET_PaymMode;
        
        value = strScan(methodOfPaymeJL,_custVendPaymProposalLine.PaymMode,1,strLen(methodOfPaymeJL));

        lgName = LedgerJournalName::find(ledgerJournalTable::find(_ledgerJournalTrans.JournalNum).JournalName);
       
        if(!value && (lgName.JournalName == 'VENPPLUS' || lgName.JournalName == 'VENCHQ'  || lgName.JournalName == 'VENPAYM'))
        {
            throw Error ("@MET:MethodOfPayMCanNot");
        }
        return LedgerJournalTransVar;
    }
